<script setup lang="ts">import { computed,onMounted,ref } from 'vue';import { useRoute } from 'vue-router';import { fetchPaper,type Paper } from '../../api/teacher/papers';import ScientificText from '../../components/question/ScientificText.vue';import AnswerDisplay from '../../components/question/AnswerDisplay.vue';const route=useRoute();const paper=ref<Paper>();const answer=computed(()=>route.params.version==='answer');onMounted(async()=>paper.value=await fetchPaper(Number(route.params.id)))</script>
<template><main v-if="paper" class="paper-preview"><header><div><h1>{{ paper.name }}</h1><p>{{ paper.subjectName }} · 总分 {{ paper.totalScore }}</p></div><button type="button" @click="window.print()">打印 / 另存为 PDF</button></header><article v-for="q in paper.questions" :key="q.id" class="paper-question"><h2>{{ q.order }}. <ScientificText :content="q.stem"/> <small>（{{ q.score }} 分）</small></h2><ol v-if="q.options.length" class="options"><li v-for="o in q.options" :key="o.label">{{ o.label }}. <ScientificText :content="o.content"/></li></ol><div v-else class="answer-space"></div><section v-if="answer" class="paper-answer"><strong>正确答案</strong><AnswerDisplay :question-type="q.questionType" :value="q.correctAnswer" :options="q.options" /><strong>STANDARD 解析</strong><ScientificText :content="q.standardAnalysis"/><p>知识点：{{ q.knowledgePoints.join('、') }} · 难度 {{ q.difficulty }}</p></section></article></main></template>
<style scoped>@page{size:A4;margin:16mm}.paper-preview{max-width:850px;margin:auto;padding:28px;color:#111;background:#fff}.paper-preview header{display:flex;justify-content:space-between;border-bottom:2px solid #111}.paper-question{break-inside:avoid;margin:22px 0}.paper-question h2{font-size:16px;font-weight:500}.options{display:grid;grid-template-columns:1fr 1fr;gap:8px}.answer-space{height:64px;border-bottom:1px solid #bbb}.paper-answer{margin-top:12px;padding:12px;border-left:3px solid #236b64;background:#f3f7f6}@media print{header button{display:none}.paper-preview{padding:0;max-width:none}.paper-answer{print-color-adjust:exact}}</style>
